$file = "frmadmindashboard.vb"
$content = Get-Content $file -Raw

# 1. Clear Paid
$patternClear = "(?s)(For Each row As DataRow In rowsToDelete\r?\n\s*ParkingData\.ParkingTable\.Rows\.Remove\(row\)\r?\n\s*Next)"
$replaceClear = "$1`r`n                                                  ' --- MySQL sync: Burahin ang mga bayad na sa phpMyAdmin ---`r`n                                                  Try`r`n                                                      Using conn As MySqlConnection = GetConnection()`r`n                                                          If conn IsNot Nothing Then`r`n                                                              Dim clrCmd As New MySqlCommand(`"DELETE FROM tblparkingrecord WHERE PaidStatus = 'Paid'`", conn)`r`n                                                              clrCmd.ExecuteNonQuery()`r`n                                                          End If`r`n                                                      End Using`r`n                                                  Catch ex As MySqlException`r`n                                                      MessageBox.Show(`"Warning: Hindi na-sync sa database. `" & ex.Message, `"Database Sync Error`", MessageBoxButtons.OK, MessageBoxIcon.Warning)`r`n                                                  End Try"
$content = [regex]::Replace($content, $patternClear, $replaceClear)

# 2. Cancel Parking (dgvVehicles)
$patternCancel = "(?s)(row\.Delete\(\)\r?\n\s*Exit For\r?\n\s*End If\r?\n\s*Next\r?\n\s*ParkingData\.ParkingTable\.AcceptChanges\(\))"
$replaceCancel = "deletedCode = row(`"Code`").ToString()`r`n                                                                $1`r`n                                                        ' MySQL Sync - Burahin sa phpMyAdmin`r`n                                                        If deletedCode <> `"`" Then`r`n                                                            Try`r`n                                                                Using conn As MySqlConnection = GetConnection()`r`n                                                                    If conn IsNot Nothing Then`r`n                                                                        Dim delCmd As New MySqlCommand(`"DELETE FROM tblparkingrecord WHERE code = @code`", conn)`r`n                                                                        delCmd.Parameters.AddWithValue(`"@code`", deletedCode)`r`n                                                                        delCmd.ExecuteNonQuery()`r`n                                                                    End If`r`n                                                                End Using`r`n                                                            Catch ex As MySqlException`r`n                                                                MessageBox.Show(`"Warning: Hindi na-sync sa database. `" & ex.Message, `"Database Sync Error`", MessageBoxButtons.OK, MessageBoxIcon.Warning)`r`n                                                            End Try`r`n                                                        End If"
# Also need to declare deletedCode before the loop:
$content = [regex]::Replace($content, $patternCancel, $replaceCancel)
$content = [regex]::Replace($content, "(?s)(If OverlayHelper\.ShowDialog\(Me, confirmDlg\) = DialogResult\.Yes Then\r?\n\s*For Each row As DataRow In ParkingData\.ParkingTable\.Rows\r?\n\s*If row\(`"PlateNumber`"\)\.ToString\(\) = plate AndAlso row\(`"Slot`"\)\.ToString\(\) = slot Then)", "If OverlayHelper.ShowDialog(Me, confirmDlg) = DialogResult.Yes Then`r`n                                                        Dim deletedCode As String = `"`"`r`n                                                        For Each row As DataRow In ParkingData.ParkingTable.Rows`r`n                                                            If row(`"PlateNumber`").ToString() = plate AndAlso row(`"Slot`").ToString() = slot Then")

# 3. Reserve
$patternReserve = "(?s)(ParkingData\.ParkingTable\.Rows\.Add\(newRow\))"
$replaceReserve = "$1`r`n                                                      ' --- MySQL sync: I-insert sa phpMyAdmin ---`r`n                                                      Try`r`n                                                          Dim tellerID As Object = DBNull.Value`r`n                                                          Dim customerID As Object = DBNull.Value`r`n`r`n                                                          If Form1.CurrentUserRole = `"Teller`" Then`r`n                                                              tellerID = GetCurrentUserID(`"Teller`", Form1.CurrentUsername)`r`n                                                          ElseIf Form1.CurrentUserRole = `"Customer`" Then`r`n                                                              customerID = GetCurrentUserID(`"Customer`", Form1.CurrentUsername)`r`n                                                          End If`r`n`r`n                                                          Using conn As MySqlConnection = GetConnection()`r`n                                                              If conn IsNot Nothing Then`r`n                                                                  Dim insCmd As New MySqlCommand(`"INSERT INTO tblparkingrecord (code, PlateNumber, VehicleType, Slot, RateName, Rate, Duration, PaidStatus, ReservationDate, CustomerID, TellerID) `" &`r`n                                                                      `"VALUES (@code, @plate, @vtype, @slot, @ratename, @rate, @totaltime, @paidstatus, @resdate, @custid, @tellid)`", conn)`r`n                                                                  insCmd.Parameters.AddWithValue(`"@code`", newRow(`"Code`").ToString())`r`n                                                                  insCmd.Parameters.AddWithValue(`"@plate`", resPlate)`r`n                                                                  insCmd.Parameters.AddWithValue(`"@vtype`", newRow(`"VehicleType`").ToString())`r`n                                                                  insCmd.Parameters.AddWithValue(`"@slot`", slotName)`r`n                                                                  insCmd.Parameters.AddWithValue(`"@ratename`", `"Standard`")`r`n                                                                  insCmd.Parameters.AddWithValue(`"@rate`", newRow(`"Rate`"))`r`n                                                                  insCmd.Parameters.AddWithValue(`"@totaltime`", `"0 hour(s)`")`r`n                                                                  insCmd.Parameters.AddWithValue(`"@paidstatus`", `"Reserved`")`r`n                                                                  insCmd.Parameters.AddWithValue(`"@resdate`", resDate)`r`n                                                                  insCmd.Parameters.AddWithValue(`"@custid`", customerID)`r`n                                                                  insCmd.Parameters.AddWithValue(`"@tellid`", tellerID)`r`n                                                                  insCmd.ExecuteNonQuery()`r`n                                                              End If`r`n                                                          End Using`r`n                                                      Catch ex As MySqlException`r`n                                                          MessageBox.Show(`"Warning: Hindi na-sync sa database. `" & ex.Message, `"Database Sync Error`", MessageBoxButtons.OK, MessageBoxIcon.Warning)`r`n                                                      End Try"
$content = [regex]::Replace($content, $patternReserve, $replaceReserve)

# 4. Cancel Reservation
$patternCancelRes = "(?s)(row\.Delete\(\)\r?\n\s*Exit For\r?\n\s*End If\r?\n\s*Next\r?\n\s*ParkingData\.ParkingTable\.AcceptChanges\(\))"
$replaceCancelRes = "canceledCode = row(`"Code`").ToString()`r`n                                                                  $1`r`n                                                            ' --- MySQL sync: Burahin sa phpMyAdmin ---`r`n                                                            If canceledCode <> `"`" Then`r`n                                                                Try`r`n                                                                    Using conn As MySqlConnection = GetConnection()`r`n                                                                        If conn IsNot Nothing Then`r`n                                                                            Dim delCmd As New MySqlCommand(`"DELETE FROM tblparkingrecord WHERE code = @code`", conn)`r`n                                                                            delCmd.Parameters.AddWithValue(`"@code`", canceledCode)`r`n                                                                            delCmd.ExecuteNonQuery()`r`n                                                                        End If`r`n                                                                    End Using`r`n                                                                Catch ex As MySqlException`r`n                                                                    MessageBox.Show(`"Warning: Hindi na-sync sa database. `" & ex.Message, `"Database Sync Error`", MessageBoxButtons.OK, MessageBoxIcon.Warning)`r`n                                                                End Try`r`n                                                            End If"
# Note that this will also match the first Cancel Parking if we are not careful, but the first one was already replaced! So this will match the second one.
$content = [regex]::Replace($content, $patternCancelRes, $replaceCancelRes)
$content = [regex]::Replace($content, "(?s)(If OverlayHelper\.ShowDialog\(Me, confirmDlg\) = DialogResult\.Yes Then\r?\n\s*For Each row As DataRow In ParkingData\.ParkingTable\.Rows\r?\n\s*If row\(`"Slot`"\)\.ToString\(\) = slotName AndAlso row\(`"PaidStatus`"\)\.ToString\(\) = `"Reserved`" Then)", "If OverlayHelper.ShowDialog(Me, confirmDlg) = DialogResult.Yes Then`r`n                                                          Dim canceledCode As String = `"`"`r`n                                                          For Each row As DataRow In ParkingData.ParkingTable.Rows`r`n                                                              If row(`"Slot`").ToString() = slotName AndAlso row(`"PaidStatus`").ToString() = `"Reserved`" Then")

# 5. CheckIn
$patternCheckIn = "(?s)(row\(`"CheckIn`"\) = DateTime\.Now\r?\n\s*Exit For\r?\n\s*End If\r?\n\s*Next)"
$replaceCheckIn = "$1`r`n                                                        ' --- MySQL sync: I-update sa phpMyAdmin ---`r`n                                                        If checkedInCode <> `"`" Then`r`n                                                            Try`r`n                                                                Using conn As MySqlConnection = GetConnection()`r`n                                                                    If conn IsNot Nothing Then`r`n                                                                        Dim updCmd As New MySqlCommand(`"UPDATE tblparkingrecord SET PaidStatus = 'Not Paid', CheckIn = @checkin WHERE code = @code`", conn)`r`n                                                                        updCmd.Parameters.AddWithValue(`"@checkin`", checkInTime)`r`n                                                                        updCmd.Parameters.AddWithValue(`"@code`", checkedInCode)`r`n                                                                        updCmd.ExecuteNonQuery()`r`n                                                                    End If`r`n                                                                End Using`r`n                                                            Catch ex As MySqlException`r`n                                                                MessageBox.Show(`"Warning: Hindi na-sync sa database. `" & ex.Message, `"Database Sync Error`", MessageBoxButtons.OK, MessageBoxIcon.Warning)`r`n                                                            End Try`r`n                                                        End If"
$content = [regex]::Replace($content, $patternCheckIn, $replaceCheckIn)

$content = [regex]::Replace($content, "(?s)(ElseIf manageDlg\.SelectedAction = `"CheckIn`" Then\r?\n\s*For Each row As DataRow In ParkingData\.ParkingTable\.Rows\r?\n\s*If row\(`"Slot`"\)\.ToString\(\) = slotName AndAlso row\(`"PaidStatus`"\)\.ToString\(\) = `"Reserved`" Then\r?\n\s*row\(`"PaidStatus`"\) = `"Not Paid`"\r?\n\s*row\(`"CheckIn`"\) = DateTime\.Now)", "ElseIf manageDlg.SelectedAction = `"CheckIn`" Then`r`n                                                      Dim checkedInCode As String = `"`"`r`n                                                      Dim checkInTime As DateTime = DateTime.Now`r`n                                                      For Each row As DataRow In ParkingData.ParkingTable.Rows`r`n                                                          If row(`"Slot`").ToString() = slotName AndAlso row(`"PaidStatus`").ToString() = `"Reserved`" Then`r`n                                                              row(`"PaidStatus`") = `"Not Paid`"`r`n                                                              row(`"CheckIn`") = checkInTime`r`n                                                              checkedInCode = row(`"Code`").ToString()")

Set-Content -Path $file -Value $content -NoNewline
